INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','movement-prepositions','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"movement-prepositions","title":"Prepositions of movement and direction","level":"A2","order":19,"summary":"Follow a route through space and distinguish a position from a change of position.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A destination or entry","Leaving and crossing","Following or approaching","Read the whole route"],"rules":[{"title":"A destination or entry","explanation":"To points to a destination; into emphasises movement from outside to inside. In usually describes an inside position. Onto highlights movement to a surface, while on commonly describes contact or position on that surface.","pattern":"We went **to** the station and **into** the building.","commonMistakes":["Go home normally has no to because home functions adverbially in this construction."],"examples":["Choose the route preposition: “We walked **into** the studio.” The route is from outside to inside the studio.","Choose the route preposition: “We walked **into** the cottage.” The route is from outside to inside the cottage."],"skill":"form"},{"title":"Leaving and crossing","explanation":"Out of indicates movement from inside to outside. Across usually describes travel from one side of a space or surface to another. Through describes travel within an opening, passage or surrounding area. The physical route makes the difference.","pattern":"Walk **across** the road, then **through** the gate.","commonMistakes":["Across a tunnel suggests crossing its width or going over its location; through a tunnel follows its interior route."],"examples":["What route does “walk into the studio” describe in this exercise? → **from outside to inside the studio**","What route does “walk into the cottage” describe in this exercise? → **from outside to inside the cottage**"],"skill":"meaning"},{"title":"Following or approaching","explanation":"Along follows the length of something such as a path or river. Towards indicates direction but does not necessarily imply arrival. Past means movement beyond a point; around can describe a route surrounding or avoiding something.","pattern":"Walk **along** the path **towards** the bridge.","commonMistakes":["Towards does not by itself say that the destination was reached."],"examples":["After walking into the studio, we went **—** home. Choose the usual adverbial home construction.","After walking into the cottage, we went **—** home. Choose the usual adverbial home construction."],"skill":"contrast"},{"title":"Read the whole route","explanation":"A route can combine several prepositions because each describes a different relation. Identify starting point, boundary, path and destination. Some movements allow several descriptions, so these questions specify the intended route rather than treating all alternatives as wrong in every context.","pattern":"Go **out of** the house, **across** the square and **into** the café.","commonMistakes":["In and into can overlap with some verbs. The questions explicitly test the entry/exit distinction."],"examples":["After walking into the studio, we walked towards the station. What does “towards” establish? → **The direction, without necessarily establishing arrival.**","After walking into the cottage, we walked towards the station. What does “towards” establish? → **The direction, without necessarily establishing arrival.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Follow a route through space and distinguish a position from a change of position.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"A destination or entry","explanation":"To points to a destination; into emphasises movement from outside to inside. In usually describes an inside position. Onto highlights movement to a surface, while on commonly describes contact or position on that surface.","pattern":"We went **to** the station and **into** the building.","commonMistakes":["Go home normally has no to because home functions adverbially in this construction."],"examples":["Choose the route preposition: “We walked **into** the studio.” The route is from outside to inside the studio.","Choose the route preposition: “We walked **into** the cottage.” The route is from outside to inside the cottage."],"skill":"form","id":"movement-prepositions-foundation-1","domain":"prepositions","referenceIds":["bc-prepositions-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Leaving and crossing","explanation":"Out of indicates movement from inside to outside. Across usually describes travel from one side of a space or surface to another. Through describes travel within an opening, passage or surrounding area. The physical route makes the difference.","pattern":"Walk **across** the road, then **through** the gate.","commonMistakes":["Across a tunnel suggests crossing its width or going over its location; through a tunnel follows its interior route."],"examples":["What route does “walk into the studio” describe in this exercise? → **from outside to inside the studio**","What route does “walk into the cottage” describe in this exercise? → **from outside to inside the cottage**"],"skill":"meaning","id":"movement-prepositions-foundation-2","domain":"prepositions","referenceIds":["bc-prepositions-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Following or approaching","explanation":"Along follows the length of something such as a path or river. Towards indicates direction but does not necessarily imply arrival. Past means movement beyond a point; around can describe a route surrounding or avoiding something.","pattern":"Walk **along** the path **towards** the bridge.","commonMistakes":["Towards does not by itself say that the destination was reached."],"examples":["After walking into the studio, we went **—** home. Choose the usual adverbial home construction.","After walking into the cottage, we went **—** home. Choose the usual adverbial home construction."],"skill":"contrast","id":"movement-prepositions-foundation-3","domain":"prepositions","referenceIds":["bc-prepositions-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Read the whole route","explanation":"A route can combine several prepositions because each describes a different relation. Identify starting point, boundary, path and destination. Some movements allow several descriptions, so these questions specify the intended route rather than treating all alternatives as wrong in every context.","pattern":"Go **out of** the house, **across** the square and **into** the café.","commonMistakes":["In and into can overlap with some verbs. The questions explicitly test the entry/exit distinction."],"examples":["After walking into the studio, we walked towards the station. What does “towards” establish? → **The direction, without necessarily establishing arrival.**","After walking into the cottage, we walked towards the station. What does “towards” establish? → **The direction, without necessarily establishing arrival.**"],"skill":"application","id":"movement-prepositions-foundation-4","domain":"prepositions","referenceIds":["bc-prepositions-reference"],"readingVersion":"core-2026-09-v3"},{"domain":"prepositions","id":"spatial-relations-contrasts","title":"Across, through, over, along, beyond and past","explanation":"Spatial prepositions select different aspects of a route or location. Across crosses a surface or area; through presents an interior or passage; along follows a line. Over may describe a higher position or a route crossing above something. Beyond and past relate a point to a reference boundary. Real scenes can support more than one description.","pattern":"**through** the tunnel / **across** the bridge","examples":["We walked **along the river**.","The village lies **beyond the hills**."],"commonMistakes":["Above and over overlap, but not everywhere: an aircraft flew over the city describes a route, while a light above the desk describes relative position."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["We went **to** the station and **into** the building.","Walk **across** the road, then **through** the gate.","Walk **along** the path **towards** the bridge.","Go **out of** the house, **across** the square and **into** the café."],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["prepositions-of-place"],"readingReferenceIds":["bc-prepositions-reference","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='movement-prepositions'
